package com.bank.evolution.stage;

// The ordered evolution stages, each relieving the previous bottleneck.
public enum ArchitectureStage {
    SINGLE_SERVER_INDEXES("Optimize queries + indexes on single DB", 1_000),
    STATELESS_LB("Stateless app + load balancer", 20_000),
    CACHE_REPLICAS_CDN("Cache + read replicas + CDN", 150_000),
    ASYNC_RATE_LIMIT("Async message queue + rate limiting", 400_000),
    MICROSERVICES_SHARDING("Microservices + DB sharding", 1_000_000),
    AUTOSCALE_MULTIREGION("Auto-scaling + multi-region", 10_000_000);

    private final String description;
    private final int maxUsers;   // rough capacity ceiling of this stage

    ArchitectureStage(String description, int maxUsers) {
        this.description = description;
        this.maxUsers = maxUsers;
    }
    public String getDescription() { return description; }
    public int getMaxUsers() { return maxUsers; }
}
