package com.bank.evolution.model;

import com.bank.evolution.stage.ArchitectureStage;

// Maps the current stage to the bottleneck that appears when it is outgrown.
public class CapacityModel {
    public boolean isOutgrown(ArchitectureStage stage, int currentUsers) {
        return currentUsers > stage.getMaxUsers();
    }

    // The bottleneck that shows up as this stage is exceeded.
    public Bottleneck bottleneckAt(ArchitectureStage stage) {
        switch (stage) {
            case SINGLE_SERVER_INDEXES:   return Bottleneck.DATABASE_QUERIES;
            case STATELESS_LB:            return Bottleneck.APP_SERVER_CPU;
            case CACHE_REPLICAS_CDN:      return Bottleneck.DATABASE_READS;
            case ASYNC_RATE_LIMIT:        return Bottleneck.WRITE_THROUGHPUT;
            case MICROSERVICES_SHARDING:  return Bottleneck.MONOLITH_AND_WRITES;
            case AUTOSCALE_MULTIREGION:   return Bottleneck.MANUAL_SCALING_SINGLE_REGION;
            default:                      return Bottleneck.NONE;
        }
    }
}
