package com.bank.evolution.advisor;

import com.bank.evolution.model.Bottleneck;
import com.bank.evolution.model.CapacityModel;
import com.bank.evolution.stage.ArchitectureStage;
import java.util.logging.Logger;

// Embodies: start simple -> measure -> find bottleneck -> scale -> repeat.
public class ScalingAdvisor {
    private static final Logger log = Logger.getLogger(ScalingAdvisor.class.getName());
    private final CapacityModel model = new CapacityModel();
    private ArchitectureStage current = ArchitectureStage.SINGLE_SERVER_INDEXES;

    public ArchitectureStage getStage() { return current; }

    // MEASURE: given current load, is this stage outgrown? If so, advance ONE step.
    public void evaluate(int currentUsers) {
        log.info(() -> "MEASURE users=" + currentUsers + " at stage ["
                + current.getDescription() + "] capacity<=" + current.getMaxUsers());
        while (model.isOutgrown(current, currentUsers) && hasNext()) {
            Bottleneck b = model.bottleneckAt(current);
            ArchitectureStage next = next();
            log.warning(() -> "BOTTLENECK " + b + " -> SCALE to [" + next.getDescription() + "]");
            current = next;
        }
        if (!model.isOutgrown(current, currentUsers)) {
            log.info(() -> "STABLE at [" + current.getDescription()
                    + "] for " + currentUsers + " users");
        }
    }

    private boolean hasNext() { return current.ordinal() < ArchitectureStage.values().length - 1; }
    private ArchitectureStage next() { return ArchitectureStage.values()[current.ordinal() + 1]; }
}
