package com.bank.evolution;

import com.bank.evolution.advisor.ScalingAdvisor;
import java.util.logging.*;

public class EvolutionDemo {
    public static void main(String[] args) {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) h.setFormatter(new BankLogFormatter());
        Logger log = Logger.getLogger(EvolutionDemo.class.getName());

        ScalingAdvisor advisor = new ScalingAdvisor();

        // Load grows over time; at each point we measure and relieve ONE bottleneck.
        int[] userMilestones = { 500, 10_000, 100_000, 300_000, 900_000, 5_000_000 };
        for (int users : userMilestones) {
            advisor.evaluate(users);
            log.info(">>> Now at stage: " + advisor.getStage().getDescription());
            log.info("------------------------------------------------------------");
        }
    }
}

